from pathlib import Path
import re
root=Path('.')
main=[p for p in root.rglob('*.kt') if '/src/main/' in str(p) and '/build/' not in str(p)]
rows=[]
for p in main:
    txt=p.read_text(errors='ignore')
    rows.append((len(txt.splitlines()),len(re.findall(r'^\s*(?:override\s+|private\s+|internal\s+|public\s+|protected\s+|suspend\s+|inline\s+)*fun\s+',txt,re.M)),len(re.findall(r'@Inject|@ApplicationContext|@Singleton',txt)),str(p)))
print('=== TOP MAIN FILES ===')
for r in sorted(rows,reverse=True)[:50]: print('METRIC',*r)
print('=== GOD RISK ===')
for r in sorted(rows,reverse=True):
    if r[0]>=450 or r[1]>=25 or r[2]>=10: print('GOD_RISK',*r)
print('=== MODULE EDGES ===')
for b in sorted(root.rglob('build.gradle.kts')):
    if '/build/' in str(b): continue
    deps=re.findall(r'project\("([^"]+)"\)',b.read_text(errors='ignore'))
    if deps: print('EDGE',b,*deps)
print('=== BLE SCANNER OWNERS ===')
for p in main:
    for i,l in enumerate(p.read_text(errors='ignore').splitlines(),1):
        if re.search(r'bleScanner\.(startScanning|startFocusedScan|stopScanning)',l): print('BLE_OWNER',p,i,l.strip())
print('=== DIRECT SERVICE CALLS ===')
for p in main:
    for i,l in enumerate(p.read_text(errors='ignore').splitlines(),1):
        if 'startForegroundService(' in l or '.startService(' in l or 'ScannerServiceController.start(' in l or 'ScannerServiceController.stop(' in l: print('SERVICE_CALL',p,i,l.strip())
print('=== SMELLS ===')
for pat in ['GlobalScope','runBlocking','Thread.sleep','observeForever','TODO','FIXME','HACK']:
    hits=[]
    for p in main:
        for i,l in enumerate(p.read_text(errors='ignore').splitlines(),1):
            if pat in l: hits.append((str(p),i,l.strip()))
    print('SMELL',pat,'COUNT',len(hits))
    for h in hits[:40]: print('HIT',*h)
print('=== DOC STATUS ===')
for p in [Path('README.md'),Path('AGENTS.md'),Path('docs/ARCHITECTURE_CURRENT.md'),Path('docs/STABILITY_RECOVERY_GUIDE.md'),Path('docs/QUALITY_GATE.md'),Path('docs/SANDBOX_EXECUTION_FLOW.md')]:
    if not p.exists(): continue
    txt=p.read_text(errors='ignore')
    print('DOC',p,'LINES',len(txt.splitlines()))
    for i,l in enumerate(txt.splitlines(),1):
        if re.search(r'Phase 2|Phase 3|NEXT ACTION|device acceptance|SOFTWARE GATE|Runtime stability|Last completed milestone|Current recovery phase',l,re.I): print('DOC_LINE',p,i,l.strip())
print('STATIC_REAUDIT=PASS_COMMAND')
